# 🎮 BELENTANI AI — EDU-OS COMPLETO
**Sistema Operativo de Videojuegos Educativos | Personaje: BELENTANI (Guerrero + Cantante) | Estética: Glassmorphism · Luz Líquida · Glossy | BD + Git + Image-to-Motion**

Arquitectura total: **8 videojuegos** de géneros distintos (ritmo musical, combate RPG, runner, puzzle-memoria, karaoke con reconocimiento de voz, tower defense, speed-matching, quiz arena), un **OS web glassmórfico**, **backend FastAPI + SQLite**, **contenido versionado en Git con CI**, y **pipeline image-to-motion** que anima el retrato de Belentani.

---

## I. REPOSITORIO GIT + ESTRUCTURA + CI

```bash
# Crear repo y estructura
mkdir belentani-ai-os && cd belentani-ai-os
git init -b main
mkdir -p os/js os/css backend assets/sprites content .github/workflows

# Estructura final:
# belentani-ai-os/
# ├── os/index.html              ← BELENTANI AI OS (hub + 8 juegos)
# ├── backend/app.py             ← API FastAPI + SQLite + git-sync
# ├── backend/schema.sql         ← Banco de datos
# ├── backend/image_to_motion.py ← Retrato → GIF/spritesheet animado
# ├── assets/belentani.png       ← Retrato del guerrero/cantante
# ├── content/*.json             ← Contenido educativo versionado en Git
# └── .github/workflows/ci.yml   ← Validación automática de contenido

# Ramas por asignatura (flujo de contenido)
git checkout -b content/es-mates
git checkout -b content/ca-llengua
git checkout -b content/en-science

# Versionado de módulos educativos
git tag -a v1.0-eso -m "Contenido ESO 2º/3º completo"
git remote add origin https://github.com/TU_USUARIO/belentani-ai-os.git
git push -u origin main --tags
```

**`.github/workflows/ci.yml`** — valida todo JSON de contenido en cada push:
```yaml
name: content-ci
on: [push, pull_request]
jobs:
  validate:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-python@v5
        with: {python-version: '3.11'}
      - name: Validar contenido educativo
        run: |
          python - <<'EOF'
          import json,glob,sys
          for f in glob.glob('content/*.json'):
              d=json.load(open(f,encoding='utf-8'))
              assert isinstance(d,(dict,list)), f
          print("✅ Contenido válido:", len(glob.glob('content/*.json')), "archivos")
          EOF
```

---

## II. BANCO DE DATOS — `backend/schema.sql`

```sql
CREATE TABLE IF NOT EXISTS players(
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL UNIQUE,
  native_lang TEXT DEFAULT 'pt-BR',
  target_langs TEXT DEFAULT 'es,ca,en',
  avatar TEXT DEFAULT 'belentani',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS sessions(
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  player_id INTEGER REFERENCES players(id),
  game_code TEXT NOT NULL,
  started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  duration_s INTEGER);

CREATE TABLE IF NOT EXISTS scores(
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  player_id INTEGER REFERENCES players(id),
  game_code TEXT NOT NULL,
  score INTEGER NOT NULL,
  accuracy REAL, streak_max INTEGER,
  git_commit TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS skill_progress(
  player_id INTEGER REFERENCES players(id),
  skill TEXT NOT NULL,           -- es_vocab, ca_grammar, en_listen, math_algebra, phonetics...
  xp INTEGER DEFAULT 0, level INTEGER DEFAULT 1, mastery REAL DEFAULT 0,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(player_id, skill));

CREATE TABLE IF NOT EXISTS achievements(
  player_id INTEGER, code TEXT, unlocked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(player_id, code));

CREATE TABLE IF NOT EXISTS content_versions(
  commit_hash TEXT PRIMARY KEY, branch TEXT,
  applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
```

## `backend/app.py` — API + SQLite + Git-Sync + Servidor del OS

```python
"""BELENTANI AI — Backend Edu-OS. FastAPI + SQLite + Git content sync."""
import json, sqlite3, subprocess, pathlib
from fastapi import FastAPI
from fastapi.staticfiles import StaticFiles
from pydantic import BaseModel

ROOT = pathlib.Path(__file__).parent.parent
DB = ROOT/"backend"/"belentani.db"
app = FastAPI(title="Belentani AI Edu-OS")

def db(): 
    c = sqlite3.connect(DB); c.row_factory = sqlite3.Row
    c.executescript((ROOT/"backend"/"schema.sql").read_text(encoding="utf-8"))
    return c

def git_commit():
    try: return subprocess.run(["git","rev-parse","--short","HEAD"],cwd=ROOT,
                               capture_output=True,text=True).stdout.strip()
    except Exception: return "local"

class ScoreIn(BaseModel):
    player: int; game: str; score: int
    accuracy: float = 1.0; streak: int = 0; skills: list = []

@app.post("/players")
def create_player(name: str):
    c = db(); c.execute("INSERT OR IGNORE INTO players(name) VALUES(?)",(name,)); c.commit()
    return {"id": c.execute("SELECT id FROM players WHERE name=?",(name,)).fetchone()["id"]}

@app.post("/scores")
def add_score(s: ScoreIn):
    c = db(); commit = git_commit()
    c.execute("INSERT INTO scores(player_id,game_code,score,accuracy,streak_max,git_commit) VALUES(?,?,?,?,?,?)",
              (s.player,s.game,s.score,s.accuracy,s.streak,commit))
    for sk in s.skills:  # XP → nivel (cada 500 xp sube nivel)
        c.execute("INSERT INTO skill_progress(player_id,skill) VALUES(?,?) ON CONFLICT DO NOTHING",(s.player,sk))
        c.execute("UPDATE skill_progress SET xp=xp+?, level=1+(xp+?)/500, mastery=MIN(1,mastery+?) WHERE player_id=? AND skill=?",
                  (s.score, s.score, s.accuracy*0.05, s.player, sk))
    c.execute("""INSERT INTO achievements(player_id,code) SELECT ?,? WHERE ? AND NOT EXISTS
                 (SELECT 1 FROM achievements WHERE player_id=? AND code=?)""",
              (s.player,"CRIMSON_STREAK",s.streak>=10,s.player,"CRIMSON_STREAK"))
    c.commit(); return {"ok": True, "commit": commit}

@app.get("/progress/{pid}")
def progress(pid: int):
    c = db()
    return {"skills": [dict(r) for r in c.execute("SELECT * FROM skill_progress WHERE player_id=?",(pid,))],
            "best": [dict(r) for r in c.execute(
                "SELECT game_code,MAX(score) best FROM scores WHERE player_id=? GROUP BY game_code",(pid,))],
            "achievements": [r["code"] for r in c.execute("SELECT code FROM achievements WHERE player_id=?",(pid,))]}

@app.get("/content/all")
def content_all():
    out = {}
    for f in (ROOT/"content").glob("*.json"):
        out[f.stem] = json.loads(f.read_text(encoding="utf-8"))
    out["meta"] = {"commit": git_commit()}
    return out

@app.post("/content/pull")
def content_pull():
    r = subprocess.run(["git","pull","--ff-only"],cwd=ROOT,capture_output=True,text=True)
    c = db(); c.execute("INSERT OR REPLACE INTO content_versions VALUES(?,?,CURRENT_TIMESTAMP)",
                        (git_commit(),"main")); c.commit()
    return {"log": r.stdout or r.stderr, "commit": git_commit()}

app.mount("/", StaticFiles(directory=ROOT/"os", html=True), name="os")
app.mount("/assets", StaticFiles(directory=ROOT/"assets"), name="assets")
```

