<script>
/* ================== MOTOR BELENTANI ================== */
const $=s=>document.querySelector(s), CV=$('#cv'), CX=CV.getContext('2d'), W=960, H=540;
const BEL=new Image(); BEL.src='/assets/belentani.png';
const LANGVOX={es:'es-ES',ca:'ca-ES',en:'en-US'};
let PLAYER={id:1,name:'William'}, AC=null, G={game:null,t:0};
const rnd=(a,b)=>Math.floor(Math.random()*(b-a+1))+a;
const shuffle=a=>a.map(v=>[Math.random(),v]).sort((x,y)=>x[0]-y[0]).map(v=>v[1]);
function tone(f,d=.12,type='sine',g=.18){try{AC=AC||new(window.AudioContext||window.webkitAudioContext)();
 const o=AC.createOscillator(),v=AC.createGain();o.type=type;o.frequency.value=f;v.gain.value=g;
 o.connect(v);v.connect(AC.destination);o.start();v.gain.exponentialRampToValueAtTime(.001,AC.currentTime+d);o.stop(AC.currentTime+d);}catch(e){}}
function say(t,l){try{const u=new SpeechSynthesisUtterance(t);u.lang=LANGVOX[l]||l;u.rate=.95;speechSynthesis.speak(u);}catch(e){}}
function lev(a,b){const m=a.length,n=b.length,d=Array.from({length:m+1},(_,i)=>[i,...Array(n).fill(0)]);
 for(let j=0;j<=n;j++)d[0][j]=j;for(let i=1;i<=m;i++)for(let j=1;j<=n;j++)
 d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]===b[j-1]?0:1));return d[m][n];}
const sim=(a,b)=>{a=a.toLowerCase().trim();b=b.toLowerCase().trim();return 1-lev(a,b)/Math.max(a.length,b.length,1);};

/* ---------- Pintura glass/glossy en canvas ---------- */
function liquidBG(t){const g=CX.createLinearGradient(0,0,W,H);g.addColorStop(0,'#2a0208');g.addColorStop(.5,'#5b0719');g.addColorStop(1,'#160104');
 CX.fillStyle=g;CX.fillRect(0,0,W,H);
 for(let i=0;i<3;i++){const x=W/2+Math.sin(t*.0004+i*2)*W*.35,y=H/2+Math.cos(t*.0003+i)*H*.3;
  const r=CX.createRadialGradient(x,y,0,x,y,320);r.addColorStop(0,'rgba(255,45,85,.20)');r.addColorStop(1,'rgba(255,45,85,0)');
  CX.fillStyle=r;CX.fillRect(0,0,W,H);}}
function glass(x,y,w,h,r=18,a=.14){CX.save();CX.beginPath();CX.roundRect(x,y,w,h,r);
 CX.fillStyle=`rgba(255,255,255,${a})`;CX.fill();CX.strokeStyle='rgba(255,255,255,.35)';CX.lineWidth=1.5;CX.stroke();CX.restore();}
function gloss(x,y,w,h,r=18){const g=CX.createLinearGradient(0,y,0,y+h);g.addColorStop(0,'rgba(255,255,255,.30)');
 g.addColorStop(.45,'rgba(255,255,255,.06)');g.addColorStop(.5,'rgba(255,255,255,0)');
 CX.beginPath();CX.roundRect(x,y,w,h,r);CX.fillStyle=g;CX.fill();}
function glossCircle(x,y,r){const g=CX.createRadialGradient(x-r*.35,y-r*.4,r*.1,x,y,r);
 g.addColorStop(0,'rgba(255,255,255,.75)');g.addColorStop(.35,'rgba(255,255,255,.12)');g.addColorStop(1,'rgba(255,255,255,0)');
 CX.beginPath();CX.arc(x,y,r,0,7);CX.fillStyle=g;CX.fill();}
function drawBel(x,y,s,t,glow=1){CX.save();CX.shadowColor=`rgba(255,45,85,${.6*glow})`;CX.shadowBlur=30+12*Math.sin(t*.005);
 CX.beginPath();CX.arc(x,y,s/2,0,7);CX.clip();if(BEL.complete)CX.drawImage(BEL,x-s/2,y-s/2,s,s);CX.restore();glossCircle(x,y,s/2);}
function monster(x,y,r,t,tier){CX.save();CX.shadowColor='#ff2d55';CX.shadowBlur=26;
 CX.beginPath();for(let i=0;i<=40;i++){const a=i/40*Math.PI*2,rr=r+Math.sin(a*(3+tier)+t*.004)*10;
 CX.lineTo(x+Math.cos(a)*rr,y+Math.sin(a)*rr);}CX.closePath();
 CX.fillStyle=tier==2?'#5b0719':tier==1?'#7a0c20':'#9c1029';CX.fill();CX.restore();
 CX.fillStyle='#ffd7de';CX.shadowColor='#ff2d55';CX.shadowBlur=16;
 CX.beginPath();CX.arc(x-r*.3,y-r*.15,7,0,7);CX.arc(x+r*.3,y-r*.15,7,0,7);CX.fill();CX.shadowBlur=0;}
function hpbar(x,y,w,v,max,label){glass(x,y,w,26,13,.12);gloss(x,y,w,26,13);
 const p=Math.max(0,v/max);CX.beginPath();CX.roundRect(x+3,y+3,(w-6)*p,20,10);
 const g=CX.createLinearGradient(x,0,x+w,0);g.addColorStop(0,'#ff2d55');g.addColorStop(1,'#ff8fa3');CX.fillStyle=g;CX.fill();
 CX.fillStyle='#fff';CX.font='700 12px system-ui';CX.textAlign='left';CX.fillText(label+` ${Math.max(0,Math.round(v))}/${max}`,x+8,y+17);}
function HUD(score,combo){glass(12,12,220,52,16,.16);gloss(12,12,220,52,16);
 CX.fillStyle='#fff';CX.font='700 20px system-ui';CX.textAlign='left';CX.fillText('⭐ '+score,26,36);
 CX.fillStyle='#ff8fa3';CX.font='700 14px system-ui';CX.fillText('🔥 racha: '+combo,26,54);}
function title(t){glass(W/2-300,20,600,56,28,.18);gloss(W/2-300,20,600,56,28);
 CX.fillStyle='#fff';CX.font='800 24px system-ui';CX.textAlign='center';CX.fillText(t,W/2,50);}
function drawBtns(){for(const b of(G.game.buttons||[])){glass(b.x,b.y,b.w,b.h,14,.16);gloss(b.x,b.y,b.w,b.h,14);
 CX.fillStyle='#fff';CX.font='600 18px system-ui';CX.textAlign='center';CX.textBaseline='middle';
 CX.fillText(b.label,b.x+b.w/2,b.y+b.h/2);}CX.textBaseline='alphabetic';}
const hitBtn=(x,y)=>(G.game.buttons||[]).find(b=>x>=b.x&&x<=b.x+b.w&&y>=b.y&&y<=b.y+b.h)||null;

