function report(score,acc,streak,skills){fetch('/scores',{method:'POST',headers:{'Content-Type':'application/json'},
 body:JSON.stringify({player:PLAYER.id,game:G.game.code,score,accuracy:acc,streak,skills})}).catch(()=>{});}
