 $('#rTitle').textContent='🏆 '+G.game.name;$('#rBody').innerHTML=`Puntuación: <b>${score}</b> · Precisión: <b>${Math.round(acc*100)}%</b> · Racha máx: <b>${streak}</b><br>${msg||'¡Belentani está orgulloso de ti, guerrero!'}`;
 $('#result').style.display='flex';}
