/* ================== JUEGO 1: RITMO DE LENGUAS (Belentani CANTANTE) ================== */
GAMES={};
GAMES.RHYM={name:'Ritmo de Lenguas 🎵',init(){this.state='pick';this.buttons=[{x:170,y:250,w:180,h:60,id:'es',label:'🇪 ESPAÑOL'},{x:390,y:250,w:180,h:60,id:'ca',label:' CATALÀ'},{x:610,y:250,w:180,h:60,id:'en',label:'🇬🇧 ENGLISH'}];},
 start(l){this.lang=l;this.state='play';this.t=0;this.idx=0;this.notes=[];this.score=0;this.combo=0;this.streak=0;this.hits=0;
  this.words=(CONTENT.lyrics[l]||[]).join(' ').split(' ').filter(Boolean);this.buttons=[];},
 update(dt){if(this.state!='play')return;this.t+=dt;
  while(this.idx<this.words.length&&this.idx*.65<this.t){this.notes.push({w:this.words[this.idx],hit:this.idx*.65+3,lane:this.idx%4,done:0});this.idx++;}
  for(const n of this.notes)if(!n.done&&this.t>n.hit+.35){n.done=-1;this.combo=0;}
  if(this.idx>=this.words.length&&this.notes.length&&this.notes.every(n=>n.done))this.end();},
 hit(lane){if(this.state!='play')return;const n=this.notes.find(n=>!n.done&&n.lane==lane&&Math.abs(n.hit-this.t)<.35);
  if(n){n.done=1;this.hits++;this.combo++;this.streak=Math.max(this.streak,this.combo);this.score+=100+this.combo*10;tone(320+lane*110,.15,'triangle');say(n.w,this.lang);}
  else{this.combo=0;tone(110,.2,'sawtooth');}},
 onKey(k){const m={d:0,f:1,j:2,k:3};if(m[k]!==undefined)this.hit(m[k]);},
 onClick(x,y){if(this.state=='pick'){const b=hitBtn(x,y);if(b)this.start(b.id);}else this.hit(Math.min(3,Math.floor(x/(W/4))));},
 draw(t){liquidBG(t);if(this.state=='pick'){title('🎤 BELENTANI CANTA: ELIGE IDIOMA');drawBtns();drawBel(W/2,400,150,t);return;}
  for(let i=0;i<4;i++){glass(i*W/4+10,70,W/4-20,H-140,16,.07);CX.fillStyle='#ff8fa3';CX.font='700 24px system-ui';CX.textAlign='center';CX.fillText('DFJK'[i],i*W/4+W/8,H-46);}
  glass(W/2-320,12,640,44,22,.18);gloss(W/2-320,12,640,44,22);CX.fillStyle='#fff';CX.font='600 19px system-ui';CX.textAlign='center';
  CX.fillText('🎶 '+this.words.slice(Math.max(0,this.idx-7),this.idx+1).join(' '),W/2,40);
  for(const n of this.notes){if(n.done)continue;const y=H-95-(n.hit-this.t)*180;if(y<60||y>H)continue;const x=n.lane*W/4+W/8;
   CX.save();CX.shadowColor='#ff2d55';CX.shadowBlur=24;CX.beginPath();CX.arc(x,y,26,0,7);CX.fillStyle='#c8102e';CX.fill();CX.restore();glossCircle(x,y,26);}
  HUD(this.score,this.combo);},
 end(){finish(this.score,this.hits/Math.max(1,this.words.length),this.streak,[this.lang+'_listen'],'¡Tu voz cruza fronteras, cantante!');}};

/* ================== JUEGO 2: COMBATE MATEMÁTICO CARMESÍ (Belentani GUERRERO) ================== */
GAMES.COMBAT={name:'Combate Matemático ⚔️',init(){this.pi=0;this.php=100;this.E=[{n:'SLIME DE SINTAXIS',hp:60},{n:'FANTASMA FALSOS AMIGOS',hp:90},{n:'DRAGÓN IGNORANCIA',hp:140}];
 this.ehp=this.E[0].hp;this.streak=0;this.score=0;this.slash=0;this.shake=0;this.round();},
 round(){const x=rnd(2,12),a=rnd(2,6),b=rnd(1,9);this.ans=x;this.q=`${a}x + ${b} = ${a*x+b}`;
  let o=[...new Set([x,x+rnd(1,3),x-rnd(1,2),x+rnd(4,7)])].slice(0,4);if(!o.includes(x))o[0]=x;this.opts=shuffle(o);
  this.buttons=this.opts.map((v,i)=>({x:120+i*190,y:460,w:160,h:56,id:i,label:String(v)}));},
 onClick(x,y){const b=hitBtn(x,y);if(!b)return;
  if(this.opts[b.id]===this.ans){this.streak++;this.score+=150+this.streak*20;this.slash=.5;this.ehp-=25+this.streak*3;tone(660,.15,'triangle');}
  else{this.streak=0;this.php-=12;this.shake=.4;tone(110,.25,'sawtooth');}
  if(this.ehp<=0){this.pi++;if(this.pi>=3)return finish(this.score,1,this.streak,['math_algebra'],'¡Has derrotado a los 3 jefes, guerrero carmesí!');this.ehp=this.E[this.pi].hp;}
  if(this.php<=0)return finish(this.score,.4,this.streak,['math_algebra'],'Caíste en batalla... ¡Repasa y vuelve!');
  this.round();},
 update(dt){this.slash=Math.max(0,this.slash-dt);this.shake=Math.max(0,this.shake-dt);},
 draw(t){liquidBG(t);CX.save();if(this.shake)CX.translate(rnd(-6,6),rnd(-4,4));
  drawBel(170,300,230,t);monster(W-200,290,110+this.pi*28,t,this.pi);
  hpbar(50,60,320,this.php,100,'BELENTANI');hpbar(W-380,60,330,this.ehp,this.E[this.pi].hp,this.E[this.pi].n);
  glass(W/2-270,150,540,92,22,.16);gloss(W/2-270,150,540,92,22);
  CX.fillStyle='#fff';CX.font='800 42px system-ui';CX.textAlign='center';CX.fillText('⚔️ '+this.q+'  →  x = ?',W/2,208);
  if(this.slash>0){CX.strokeStyle=`rgba(255,60,90,${Math.min(1,this.slash*2)})`;CX.lineWidth=12;CX.shadowColor='#ff2d55';CX.shadowBlur=34;
   CX.beginPath();CX.arc(W-200,290,150,-.7,.9);CX.stroke();CX.shadowBlur=0;}
  drawBtns();CX.restore();HUD(this.score,this.streak);}};

/* ================== JUEGO 3: SYNTAX RUNNER (Runner 3 carriles) ================== */
GAMES.RUNNER={name:'Syntax Runner 🏃',init(){this.L=[190,300,410];this.lane=1;this.items=[];this.t=0;this.sp=250;this.hp=100;this.score=0;this.streak=0;this.next=0;this.prompt();},
 prompt(){this.cur=shuffle(CONTENT.ff)[0];},
 update(dt){this.t+=dt;this.sp+=5*dt;this.next-=dt;
  if(this.next<=0){this.next=1.05;const good=Math.random()<.55;
   this.items.push({w:good?this.cur.es:this.cur.trap,good,lane:rnd(0,2),x:W+80});}
  for(const it of this.items)it.x-=this.sp*dt;
  for(const it of this.items){if(it.hit)continue;
   if(Math.abs(it.x-150)<52&&it.lane==this.lane){it.hit=1;
    if(it.good){this.score+=100;this.streak++;tone(700,.12,'triangle');this.prompt();}
    else{this.hp-=20;this.streak=0;this.shake=.35;tone(120,.25,'sawtooth');}}}
  this.items=this.items.filter(i=>i.x>-90&&!i.gone);this.shake=Math.max(0,(this.shake||0)-dt);
  if(this.hp<=0)finish(this.score,.5,this.streak,['es_vocab'],'El runner terminó. ¡Reflexiona sobre los falsos amigos!');},
 onKey(k){if(k=='arrowup'||k=='w')this.lane=Math.max(0,this.lane-1);if(k=='arrowdown'||k=='s')this.lane=Math.min(2,this.lane+1);},
 onClick(x,y){this.lane=y<250?0:y<360?1:2;},
 draw(t){liquidBG(t);CX.save();if(this.shake)CX.translate(rnd(-5,5),0);
  this.L.forEach((y,i)=>{glass(40,y-42,W-80,84,20,i==this.lane?.16:.07);gloss(40,y-42,W-80,84,20);});
  glass(W/2-260,12,520,48,24,.18);gloss(W/2-260,12,520,48,24);CX.fillStyle='#fff';CX.font='700 20px system-ui';CX.textAlign='center';
  CX.fillText(`RECOGE: "${this.cur.pt}" → traducción correcta`,W/2,42);
  for(const it of this.items){if(it.hit)continue;glass(it.x-70,this.L[it.lane]-26,140,52,26,.2);gloss(it.x-70,this.L[it.lane]-26,140,52,26);
   CX.fillStyle=it.good?'#d6ffe0':'#ffd7de';CX.font='700 19px system-ui';CX.textAlign='center';CX.fillText(it.w,it.x,this.L[it.lane]+6);}
  drawBel(150,this.L[this.lane],96,t,1.3);CX.restore();
  hpbar(50,80,260,this.hp,100,'VIDA');HUD(this.score,this.streak);}};

/* ================== JUEGO 4: MAZMORRA FALSOS AMIGOS (Memoria cruzada) ================== */
GAMES.DUNGEON={name:'Mazmorra Falsos Amigos 🧩',init(){const cs=shuffle(CONTENT.concepts).slice(0,4);this.cards=[];
  cs.forEach((c,i)=>{const pair=i%2?['ca','en']:['pt','es'];pair.forEach(l=>this.cards.push({c:c.id,lang:l,txt:c[l],up:0,ok:0}));});
  this.cards=shuffle(this.cards).map((c,i)=>({...c,i}));this.flip=[];this.lock=0;this.moves=0;this.pairs=0;this.score=0;this.buttons=[];},
 update(dt){if(this.lock>0){this.lock-=dt;if(this.lock<=0){for(const c of this.cards)if(!c.ok)c.up=0;this.flip=[];}}},
 onClick(x,y){if(this.lock>0)return;const i=this.cardAt(x,y);if(i<0)return;const c=this.cards[i];if(c.up||c.ok)return;
  c.up=1;this.flip.push(i);tone(500+this.flip.length*120,.08);
  if(this.flip.length==2){this.moves++;const[a,b]=this.flip.map(j=>this.cards[j]);
   if(a.c==b.c&&a.lang!=b.lang){a.ok=b.ok=1;this.pairs++;this.score+=200;tone(880,.2,'triangle');this.flip=[];
    if(this.pairs==this.cards.length/2)setTimeout(()=>finish(this.score,Math.min(1,this.pairs*2/Math.max(1,this.moves)),this.pairs,['es_vocab','ca_vocab'],'¡Mazmorra superada, sabio guerrero!'),400);}
   else this.lock=.9;}},
 cardAt(x,y){for(const c of this.cards){const p=this.pos(c.i);if(x>=p.x&&x<=p.x+150&&y>=p.y&&y<=p.y+100)return c.i;}return -1;},
 pos(i){return{x:120+(i%4)*190,y:110+Math.floor(i/4)*130};},
 draw(t){liquidBG(t);title('🧩 EMPAREJA IDIOMAS DEL MISMO CONCEPTO');
  for(const c of this.cards){const p=this.pos(c.i);
   if(c.up||c.ok){glass(p.x,p.y,150,100,16,c.ok?.28:.18);gloss(p.x,p.y,150,100,16);
    CX.fillStyle=c.ok?'#b8ffd0':'#fff';CX.font='700 19px system-ui';CX.textAlign='center';CX.fillText(c.txt,p.x+75,p.y+48);
    CX.fillStyle='#ff8fa3';CX.font='700 12px system-ui';CX.fillText(c.lang.toUpperCase(),p.x+75,p.y+78);}
   else{CX.save();CX.shadowColor='#ff2d55';CX.shadowBlur=14;CX.beginPath();CX.roundRect(p.x,p.y,150,100,16);
    CX.fillStyle='#7a0c20';CX.fill();CX.restore();gloss(p.x,p.y,150,100,16);
    CX.fillStyle='#ffd7de';CX.font='800 30px system-ui';CX.textAlign='center';CX.fillText('',p.x+75,p.y+62);}}
  HUD(this.score,this.pairs);}};

/* ================== JUEGO 5: KARAOKE DOJO (Voz real + reconocimiento) ================== */
GAMES.KARAOKE={name:'Karaoke Dojo 🎤',init(){this.state='pick';this.buttons=[{x:170,y:240,w:180,h:60,id:'es',label:'🇪🇸 CANTAR ES'},{x:390,y:240,w:180,h:60,id:'ca',label:'🎗 CANTAR CA'},{x:610,y:240,w:180,h:60,id:'en',label:'🇬🇧 SING EN'}];},
 start(l){this.lang=l;this.lines=CONTENT.lyrics[l]||['Hola amigo'];this.i=0;this.score=0;this.state='idle';this.fb='';this.listen=0;
  this.buttons=[{x:W/2-110,y:420,w:220,h:60,id:'sing',label:'🎤 CANTAR AHORA'}];
  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(SR){this.sr=new SR();this.sr.lang=LANGVOX[l];this.sr.onresult=e=>this.judge(e.results[0][0].transcript);this.sr.onend=()=>this.listen=0;}},
 judge(txt){const s=sim(txt,this.lines[this.i]);const pts=s>=.72?100:s>=.5?60:25;this.score+=pts;
  this.fb=`Escuché: "${txt}" → ${Math.round(s*100)}% (+${pts})`;this.i++;tone(pts==100?880:440,.2,'triangle');
  if(this.i>=this.lines.length)setTimeout(()=>finish(this.score,this.score/(this.lines.length*100),0,[this.lang+'_speak'],'¡Tu pronunciación brilla como luz líquida!'),600);},
 onClick(x,y){const b=hitBtn(x,y);if(!b)return;
  if(this.state=='pick')this.start(b.id);
  else if(b.id=='sing'){if(this.sr){this.listen=1;this.sr.start();}else this.judge(prompt('Escribe la línea cantada:')||'');}},
 update(dt){},
 draw(t){liquidBG(t);drawBel(140,300,190,t,1.4);
  if(this.state=='pick'){title('🎤 KARAOKE DOJO: ELIGE IDIOMA');drawBtns();return;}
