  CX.fillStyle='#ff8fa3';CX.font='600 16px system-ui';CX.fillText(`Línea ${this.i+1}/${this.lines.length} · ${this.lang.toUpperCase()}`,580,235);
  if(this.listen){for(let i=0;i<24;i++){const h=14+Math.abs(Math.sin(t*.01+i))*46;CX.fillStyle=`rgba(255,45,85,${.5+.4*Math.sin(t*.01+i)})`;CX.fillRect(300+i*16,340-h/2,8,h);}}
  if(this.fb){CX.fillStyle='#ffd7de';CX.font='600 18px system-ui';CX.fillText(this.fb,580,395);}
  drawBtns();HUD(this.score,0);}};

/* ================== JUEGO 6: TORRE DE PALABRAS (Tower defense) ================== */
GAMES.TOWER={name:'Torre de Palabras 🏰',init(){this.hp=100;this.kills=0;this.score=0;this.en=[];this.t=0;this.next=2;this.sp=42;this.beam=0;this.wave();this.buttons=[];},
 wave(){const p=shuffle(CONTENT.ff)[0];this.cur=p;
  let others=CONTENT.ff.filter(f=>f.pt!=p.pt).map(f=>f.es);
  this.opts=shuffle([p.es,p.trap,shuffle(others)[0]]);
  this.buttons=this.opts.map((o,i)=>({x:180+i*220,y:460,w:200,h:56,id:i,label:o}));},
 update(dt){this.t+=dt;this.beam=Math.max(0,this.beam-dt);this.next-=dt;
  if(this.next<=0){this.next=2.6;this.en.push({x:-60,w:this.cur.trap});}
  for(const e of this.en)e.x+=this.sp*dt;this.sp+=.6*dt;
  const reach=this.en.find(e=>e.x>830);if(reach){this.en=this.en.filter(e=>e!==reach);this.hp-=15;this.shake=.3;tone(100,.3,'sawtooth');}
  this.shake=Math.max(0,(this.shake||0)-dt);
  if(this.hp<=0)finish(this.score,.4,this.kills,['es_vocab'],'El castillo cayó... ¡refuerza tu vocabulario!');
  if(this.kills>=12)finish(this.score,1,this.kills,['es_vocab'],'¡Castillo defendido, comandante Belentani!');},
 onClick(x,y){const b=hitBtn(x,y);if(!b||!this.en.length)return;
  if(this.opts[b.id]===this.cur.es){this.beam=.4;this.kills++;this.score+=130;this.en.shift();tone(760,.15,'triangle');this.wave();}
  else{this.hp-=10;this.shake=.3;tone(120,.25,'sawtooth');}},
 draw(t){liquidBG(t);CX.save();if(this.shake)CX.translate(rnd(-5,5),0);
  glass(840,180,100,260,18,.2);gloss(840,180,100,260,18);CX.fillStyle='#ffd7de';CX.font='800 40px system-ui';CX.textAlign='center';CX.fillText('🏰',890,320);
  drawBel(110,320,150,t,1.2);
  for(const e of this.items||[])0;for(const e of this.en){monster(e.x,320,44,t,0);
   CX.fillStyle='#fff';CX.font='700 15px system-ui';CX.textAlign='center';CX.fillText(e.w,e.x,262);}
  if(this.beam>0&&this.en.length){CX.strokeStyle=`rgba(255,80,110,${this.beam*2.4})`;CX.lineWidth=8;CX.shadowColor='#ff2d55';CX.shadowBlur=30;
   CX.beginPath();CX.moveTo(170,320);CX.lineTo(this.en[0].x,320);CX.stroke();CX.shadowBlur=0;}
  glass(W/2-330,90,660,64,20,.16);gloss(W/2-330,90,660,64,20);
  CX.fillStyle='#fff';CX.font='700 21px system-ui';CX.textAlign='center';
  CX.fillText(`El monstruo grita "${this.cur.pt}" → ¿PALABRA CORRECTA para disparar?`,W/2,130);
  drawBtns();CX.restore();hpbar(50,60,260,this.hp,100,'CASTILLO');HUD(this.score,this.kills);}};

/* ================== JUEGO 7: ENLACES TRILINGÜES (Speed matching) ================== */
