WORDS={'es':['hola','amigo','escuela','sol'],'ca':['bon','amic','escola','sol'],'en':['hello','friend','school','sun']}
class SimonCanta(BaseGame):
    NAME='SIMON CANTA'
    def setup(self):
        self.seq=[]; self.pos=0; self.show=0; self.show_t=0; self.phase='grow'
        self.lang='es'; self.flash=-1; self.flash_t=0; self.grow()
    def grow(self):
        self.lang=random.choice(list(WORDS))
        self.seq.append(random.randint(0,3))
        self.pos=0; self.phase='show'; self.show=0; self.show_t=0
