            self.quiz=None; self.new_word(); self.reset_ball(1)
    def update(self,dt,t):
        if self.quiz: return
        k=pygame.key.get_pressed()
        mv=(k[pygame.K_DOWN] or k[pygame.K_s])-(k[pygame.K_UP] or k[pygame.K_w])
        self.py=min(H-60,max(60,self.py+mv*360*dt))
        self.ay+=max(-260*dt,min(260*dt,self.by-self.ay))
        self.bx+=self.vx*dt; self.by+=self.vy*dt
        if self.by<20 or self.by>H-20: self.vy=-self.vy
        if self.bx<60 and abs(self.by-self.py)<55 and self.vx<0:
            self.vx=abs(self.vx)*1.05; self.rally+=1
            say(self.syls[self.syl%len(self.syls)]); self.syl+=1; beep(500)
            if self.rally%4==0: self.make_quiz()
        if self.bx>W-60 and abs(self.by-self.ay)<55 and self.vx>0:
            self.vx=-abs(self.vx)*1.05; beep(380)
        if self.bx<0:
            self.lives-=1; self.streak=0
            if self.lives<=0: self.running=False
            else: self.reset_ball(1)
        if self.bx>W:
            self.score+=50; self.reset_ball(-1)
    def make_quiz(self):
        others=[w for l,w,_ in WORDS if l==self.lang and w!=self.word]
        opts=[self.word]+others[:2]
        random.shuffle(opts)
        self.quiz={'o':opts}
    def draw(self,t):
        liquid_bg(self.screen,t)
        self.screen.blit(glass(200,44,22,40),(W//2-100,8))
        text(self.screen,f"Rally: {self.rally}  ({self.lang.upper()})",W//2,30,self.f22)
        self.screen.blit(glass(18,110,9,50),(30,self.py-55))
        self.screen.blit(glass(18,110,9,50),(W-48,self.ay-55))
        if not self.quiz:
            bx,by=int(self.bx),int(self.by)
            pygame.draw.circle(self.screen,CRIM,(bx,by),12)
            pygame.draw.circle(self.screen,(255,255,255),(bx-4,by-4),4)
            if self.syl: text(self.screen,self.syls[(self.syl-1)%len(self.syls)],bx,by-30,self.f18,PINK)
        else:
            self.screen.blit(glass(620,210,24,60),(W//2-310,H//2-105))
            text(self.screen,f"Palabra escuchada en {self.lang.upper()}: cual es?",W//2,H//2-60,self.f22)
            for i,o in enumerate(self.quiz['o']):
                self.screen.blit(glass(180,54,14,40),(W//2-290+i*200,H//2))
                text(self.screen,f"{i+1}. {o}",W//2-200+i*200,H//2+27,self.f18)
        self.hud(t)

if __name__=='__main__': PongFonetico().run()
