### `src/utils/speech.ts` — 5 idiomas, voz humana, ilimitada
```ts
import type {Lang} from '../types';
export const VOX:Record<Lang,string>={es:'es-ES',ca:'ca-ES',en:'en-US',pt:'pt-BR',fr:'fr-FR'};
export const LANG_NAME:Record<Lang,string>={es:'Español',ca:'Català',en:'English',pt:'Português',fr:'Français'};
let queue:SpeechSynthesisUtterance[]=[];
function pick(lang:Lang):SpeechSynthesisVoice|undefined{
  return speechSynthesis.getVoices().find(v=>v.lang===VOX[lang]&&v.localService)
      || speechSynthesis.getVoices().find(v=>v.lang.startsWith(VOX[lang].slice(0,2)));}
export function speak(text:string,lang:Lang,opts?:{rate?:number;pitch?:number}){
  if(!('speechSynthesis' in window))return;
  const u=new SpeechSynthesisUtterance(text);
  const v=pick(lang); if(v)u.voice=v;
  u.lang=VOX[lang]; u.rate=opts?.rate??0.95; u.pitch=opts?.pitch??1.05; // calidez humana
  queue.push(u); if(queue.length===1)drain();}
function drain(){const u=queue[0]; if(!u)return; u.onend=u.onerror=()=>{queue.shift();drain();}; speechSynthesis.speak(u);}
export function stopSpeak(){speechSynthesis.cancel(); queue=[];}
export function listen(lang:Lang):Promise<string>{
  return new Promise((res,rej)=>{
    const SR=(window as any).SpeechRecognition||(window as any).webkitSpeechRecognition;
    if(!SR)return rej('STT no disponible');
    const r=new SR(); r.lang=VOX[lang]; r.interimResults=false;
    r.onresult=(e:any)=>res(e.results[0][0].transcript); r.onerror=(e:any)=>rej(e.error); r.start();});}
```

