### `src/utils/tutorEngine.ts` — motor local (sin nube) + explicador JSON
```ts
import {CULTURE} from '../data/culturalData'; import {SUBJECTS} from '../data/curriculumData';
import type {Lang} from '../types';
export function tutorReply(q:string,lang:Lang):string{
 const t=q.toLowerCase();
 if(/hola|buenas|oi|hello/.test(t))return lang==='pt'?'Oi Danilo! Pronto para jogar e aprender?':lang==='ca'?'Hola Danilo! A punt per aprendre?':'¡Hola Danilo! ¿Jugamos y aprendemos?';
 const eq=t.match(/(-?\d+)\s*x\s*([+-]\s*\d+)\s*=\s*(-?\d+)/);
 if(eq){const a=+eq[1],b=+eq[2].replace(/\s/g,''),c=+eq[3];const x=(c-b)/a;
  return `Paso 1: ${a}x = ${c} - (${b}) = ${c-b}. Paso 2: x = ${c-b}/${a} = ${x}. ¡Tú puedes, guerrero!`;}
 const cul=CULTURE.find(c=>t.split(' ').some(w=>w.length>4&&JSON.stringify(c.title).toLowerCase().includes(w)));
 if(cul)return `${cul.title[lang]}. ${cul.tip} (BR: ${cul.br})`;
 const sub=SUBJECTS.find(s=>t.includes(s.name.es.toLowerCase().slice(0,5))||t.includes(s.id));
 if(sub)return `${sub.name[lang]}: ${sub.units[3]?.[0]?.title[lang]??sub.units[1][0].title[lang]} — te preparo ejercicios y un juego.`;
 return 'Cuéntame más o pide: mates, cultura, idiomas, juegos o tu plan de hoy. Estoy aquí, sin prisa.';}
export function explainJSON(node:any,depth=0):string{
 if(depth>2)return '…nodo anidado con más detalles.';
 if(Array.isArray(node))return `Lista de ${node.length} elementos: ${typeof node[0]==='object'?'objetos con claves '+Object.keys(node[0]||{}).join(', '):typeof node[0]}.`;
 if(node&&typeof node==='object')return `Objeto con claves: ${Object.keys(node).slice(0,6).join(', ')}.`;
 return `Valor ${typeof node}: ${String(node).slice(0,40)};`;}
```

