import {GAMES200} from '../data/gamesRegistry'; import {speak,type Lang,type Game} from '../utils/speech';
import {useState,useEffect,useRef} from 'react';
export function logScore(g:Game,acc:number,streak:number){
 const s=JSON.parse(localStorage.getItem('belentani_scores')||'[]');
 s.push({game:g.id,skill:g.skill,lang:g.lang,acc,streak,ts:Date.now()});
 localStorage.setItem('belentani_scores',JSON.stringify(s.slice(-500)));}
function MiniGame({g,lang,onDone}:{g:Game;lang:Lang;onDone:(acc:number,st:number)=>void}){
 const ref=useRef<HTMLCanvasElement>(null); const [quiz]=useState(()=>Array.from({length:8},(_,i)=>({q:`${g.skill} ${g.lang}: palabra ${i+1} de ${g.genre}`,a:0})));
 const [i,setI]=useState(0); const [ok,setOk]=useState(0);
 useEffect(()=>{speak(`${g.name}. ${g.mechanic}. ¡Suerte!`,lang);},[]);
 return <div className="glass panel"><h3>{g.name}</h3>
  {i<quiz.length? <><p>{quiz[i].q}</p><div className="row">{['A','B','C'].map((o,k)=>
   <button key={o} className="chip" onClick={()=>{const hit=k===0; if(hit)setOk(ok+1); setI(i+1);
     if(i+1>=quiz.length)onDone((hit?ok+1:ok)/quiz.length,hit?3:0);}}>{o}</button>)}</div></>
   : <p>Fin · precisión {Math.round(ok/quiz.length*100)}%</p>}
  <canvas ref={ref} width={480} height={120} className="glass"/></div>;}
export default function ArcadeCenter({lang}:{lang:Lang}){
 const [q,setQ]=useState(''); const [play,setPlay]=useState<Game|null>(null);
 const list=GAMES200.filter(g=>g.name.toLowerCase().includes(q)||g.genre.toLowerCase().includes(q));
 return <section className="glass panel"><h2>Arcade · {GAMES200.length} juegos</h2>
  <input className="chip" placeholder="buscar género o nombre…" value={q} onChange={e=>setQ(e.target.value)}/>
  {play&&<MiniGame g={play} lang={lang} onDone={(a,s)=>{logScore(play,a,s); setPlay(null);}}/>}
  <div className="grid">{list.slice(0,60).map(g=>
   <button key={g.id} className={g.belentani?'glass tile bel':'glass tile'} onClick={()=>g.playable?setPlay(g):speak('Este juego se lanza en Python: play.py '+g.id,lang)}>
    <b>{g.name}</b><small>{g.genre} · {g.skill} · {g.lang} · {g.mechanic}</small>{g.belentani&&<span>🔴 pelo largo · traje rojo · barba</span>}</button>)}</div>
 </section>;}
