import {useState} from 'react'; import type {ShieldSettings} from '../types';
const DEF:ShieldSettings={dailyMin:90,curfew:'21:30',breakMin:25,externalAI:false,voice:true,pinHash:''};
async function hash(p:string){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(p));
 return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('');}
export default function ParentalShield({set,onClose}:{set:(s:ShieldSettings)=>void;onClose:()=>void}){
 const [s,setS]=useState<ShieldSettings>(JSON.parse(localStorage.getItem('shield')||JSON.stringify(DEF)));
 const [pin,setPin]=useState(''); const [ok,setOk]=useState(!s.pinHash);
 const save=async()=>{const next={...s,pinHash:s.pinHash||await hash(pin)};localStorage.setItem('shield',JSON.stringify(next));set(next);onClose();};
 const wipe=()=>{localStorage.clear(); alert('Datos de Danilo borrados del dispositivo (derecho de supresión RGPD/LOPDGDD).'); onClose();};
 return <section className="glass panel shield"><h2>🔒 Escudo parental</h2>
  {!ok? <><input type="password" className="chip" value={pin} onChange={e=>setPin(e.target.value)} placeholder="PIN parental"/>
    <button className="chip on" onClick={async()=>setOk(!s.pinHash||s.pinHash===await hash(pin))}>entrar</button></> :
   <><label className="row">Minutos/día <input type="number" value={s.dailyMin} onChange={e=>setS({...s,dailyMin:+e.target.value})}/></label>
    <label className="row">Toque de queda <input type="time" value={s.curfew} onChange={e=>setS({...s,curfew:e.target.value})}/></label>
    <label className="row">Pausa salud (min) <input type="number" value={s.breakMin} onChange={e=>setS({...s,breakMin:+e.target.value})}/></label>
    <label className="row">IA externa (OFF por defecto) <input type="checkbox" checked={s.externalAI} onChange={e=>setS({...s,externalAI:e.target.checked})}/></label>
    <ul className="muted"><li>Local-first: cero telemetría, cero cookies, cero CDN.</li>
     <li>Perfil pseudonimizado "Danilo" · cifrado AES-GCM con PIN (PBKDF2).</li>
     <li>RGPD art. 6/8/9 + LOPDGDD art. 7-9 + Guía AEPD menores · derechos exportar/suprimir.</li>
     <li>Salud: pausa 25/5, regla 20-20-20, toque de queda (OMS/UNESCO).</li></ul>
    <div className="row"><button className="chip on" onClick={save}>guardar</button>
     <button className="chip" onClick={wipe}>borrar datos</button><button className="chip" onClick={onClose}>cerrar</button></div></>}
