import {useState} from 'react'; import {SUBJECTS} from '../data/curriculumData'; import {speak,type Lang,type Score} from '../utils/speech';
export default function SuperpowerAuditoria({lang}:{lang:Lang}){
 const [rep,setRep]=useState<string[]>([]);
 const audit=()=>{const s:Score[]=JSON.parse(localStorage.getItem('belentani_scores')||'[]');
  const by:Record<string,number[]>={}; s.forEach(x=>{(by[x.skill]??=[]).push(x.acc);});
  const out:string[]=[]; const powers:string[]=[];
  for(const sk of ['vocab','mates','grammar','listen','culture']){
   const a=by[sk]||[]; const m=a.length?a.reduce((p,c)=>p+c,0)/a.length:0;
   if(!a.length)out.push(`SIN DATOS ${sk}: juega 3 partidas de ${sk} hoy.`);
   else if(m<0.6)out.push(`REPARAR ${sk} (${Math.round(m*100)}%): unidad de refuerzo + 2 juegos espaciados 48h.`);
   else powers.push(`${sk} ${Math.round(m*100)}%`);}
  if(s.some(x=>x.streak>=8))powers.push('🔥 RACHA CRISTALINA');
  if(s.length>=50)powers.push('🛡️ CONSTANCIA DE GUERRERO');
  out.push('SUPERPODERES: '+(powers.join(' · ')||'en construcción'));
  out.push('HARNESS: auditar → plan → jugar → re-auditar en 7 días.');
  setRep(out); speak(out.slice(0,2).join('. '),lang);};
 return <section className="glass panel"><h2>Auditoría · Reparación · Superpoderes</h2>
