## `backend/app.py` — API + SQLite + Git-Sync + Servidor del OS

```python
"""BELENTANI AI — Backend Edu-OS. FastAPI + SQLite + Git content sync."""
import json, sqlite3, subprocess, pathlib
from fastapi import FastAPI
from fastapi.staticfiles import StaticFiles
from pydantic import BaseModel

ROOT = pathlib.Path(__file__).parent.parent
DB = ROOT/"backend"/"belentani.db"
app = FastAPI(title="Belentani AI Edu-OS")

def db(): 
    c = sqlite3.connect(DB); c.row_factory = sqlite3.Row
    c.executescript((ROOT/"backend"/"schema.sql").read_text(encoding="utf-8"))
    return c

def git_commit():
    try: return subprocess.run(["git","rev-parse","--short","HEAD"],cwd=ROOT,
                               capture_output=True,text=True).stdout.strip()
    except Exception: return "local"

class ScoreIn(BaseModel):
    player: int; game: str; score: int
    accuracy: float = 1.0; streak: int = 0; skills: list = []

@app.post("/players")
def create_player(name: str):
    c = db(); c.execute("INSERT OR IGNORE INTO players(name) VALUES(?)",(name,)); c.commit()
    return {"id": c.execute("SELECT id FROM players WHERE name=?",(name,)).fetchone()["id"]}

@app.post("/scores")
def add_score(s: ScoreIn):
    c = db(); commit = git_commit()
    c.execute("INSERT INTO scores(player_id,game_code,score,accuracy,streak_max,git_commit) VALUES(?,?,?,?,?,?)",
              (s.player,s.game,s.score,s.accuracy,s.streak,commit))
    for sk in s.skills:  # XP → nivel (cada 500 xp sube nivel)
        c.execute("INSERT INTO skill_progress(player_id,skill) VALUES(?,?) ON CONFLICT DO NOTHING",(s.player,sk))
        c.execute("UPDATE skill_progress SET xp=xp+?, level=1+(xp+?)/500, mastery=MIN(1,mastery+?) WHERE player_id=? AND skill=?",
                  (s.score, s.score, s.accuracy*0.05, s.player, sk))
    c.execute("""INSERT INTO achievements(player_id,code) SELECT ?,? WHERE ? AND NOT EXISTS
                 (SELECT 1 FROM achievements WHERE player_id=? AND code=?)""",
              (s.player,"CRIMSON_STREAK",s.streak>=10,s.player,"CRIMSON_STREAK"))
    c.commit(); return {"ok": True, "commit": commit}

@app.get("/progress/{pid}")
def progress(pid: int):
    c = db()
    return {"skills": [dict(r) for r in c.execute("SELECT * FROM skill_progress WHERE player_id=?",(pid,))],
            "best": [dict(r) for r in c.execute(
                "SELECT game_code,MAX(score) best FROM scores WHERE player_id=? GROUP BY game_code",(pid,))],
            "achievements": [r["code"] for r in c.execute("SELECT code FROM achievements WHERE player_id=?",(pid,))]}

@app.get("/content/all")
def content_all():
    out = {}
    for f in (ROOT/"content").glob("*.json"):
        out[f.stem] = json.loads(f.read_text(encoding="utf-8"))
    out["meta"] = {"commit": git_commit()}
    return out

@app.post("/content/pull")
def content_pull():
    r = subprocess.run(["git","pull","--ff-only"],cwd=ROOT,capture_output=True,text=True)
    c = db(); c.execute("INSERT OR REPLACE INTO content_versions VALUES(?,?,CURRENT_TIMESTAMP)",
                        (git_commit(),"main")); c.commit()
    return {"log": r.stdout or r.stderr, "commit": git_commit()}

app.mount("/", StaticFiles(directory=ROOT/"os", html=True), name="os")
app.mount("/assets", StaticFiles(directory=ROOT/"assets"), name="assets")
```

