/* ================== JUEGO 2: COMBATE MATEMÁTICO CARMESÍ (Belentani GUERRERO) ================== */
GAMES.COMBAT={name:'Combate Matemático ⚔️',init(){this.pi=0;this.php=100;this.E=[{n:'SLIME DE SINTAXIS',hp:60},{n:'FANTASMA FALSOS AMIGOS',hp:90},{n:'DRAGÓN IGNORANCIA',hp:140}];
