            self.show_t=0
            if self.show<len(self.seq):
                self.flash=self.seq[self.show]; self.flash_t=0.45
                beep(300+self.flash*110); say(WORDS[self.lang][self.flash])
                self.show+=1
            else: self.phase='input'
