        if e.type!=pygame.KEYDOWN or self.phase!='input': return
        for i,p in enumerate(PADS):
            if e.key==p['k']:
                self.flash=i; self.flash_t=0.3; beep(300+i*110); say(WORDS[self.lang][i])
                self.total+=1
                if self.seq[self.pos]==i:
                    self.hits+=1; self.pos+=1
                    if self.pos>=len(self.seq):
                        self.score+=100*len(self.seq); self.add_streak(); self.grow()
                else:
                    self.lives-=1; self.streak=0
                    if self.lives<=0: self.running=False
                    else: self.phase='show'; self.show=0; self.show_t=0
    def draw(self,t):
