wf('adapt_simon_canta.py', '''"""SIMON CANTA: secuencias de palabras en ES/CA/EN con voz y tonos (lado cantante)."""
import pygame, random
from belentani_engine import *

PADS=[{'k':pygame.K_1,'x':180,'c':(255,45,85)},{'k':pygame.K_2,'x':400,'c':(255,143,163)},
      {'k':pygame.K_3,'x':620,'c':(200,16,46)},{'k':pygame.K_4,'x':840,'c':(255,90,90)}]
WORDS={'es':['hola','amigo','escuela','sol'],'ca':['bon','amic','escola','sol'],'en':['hello','friend','school','sun']}
class SimonCanta(BaseGame):
    NAME='SIMON CANTA'
    def setup(self):
        self.seq=[]; self.pos=0; self.show=0; self.show_t=0; self.phase='grow'
        self.lang='es'; self.flash=-1; self.flash_t=0; self.grow()
    def grow(self):
        self.lang=random.choice(list(WORDS))
        self.seq.append(random.randint(0,3))
        self.pos=0; self.phase='show'; self.show=0; self.show_t=0
    def update(self,dt,t):
        self.flash_t=max(0,self.flash_t-dt)
        if self.phase!='show': return
        self.show_t+=dt
        if self.show_t>0.7:
            self.show_t=0
            if self.show<len(self.seq):
                self.flash=self.seq[self.show]; self.flash_t=0.45
                beep(300+self.flash*110); say(WORDS[self.lang][self.flash])
                self.show+=1
            else: self.phase='input'
    def on_event(self,e):
        if e.type!=pygame.KEYDOWN or self.phase!='input': return
        for i,p in enumerate(PADS):
            if e.key==p['k']:
                self.flash=i; self.flash_t=0.3; beep(300+i*110); say(WORDS[self.lang][i])
                self.total+=1
                if self.seq[self.pos]==i:
                    self.hits+=1; self.pos+=1
                    if self.pos>=len(self.seq):
                        self.score+=100*len(self.seq); self.add_streak(); self.grow()
                else:
                    self.lives-=1; self.streak=0
                    if self.lives<=0: self.running=False
                    else: self.phase='show'; self.show=0; self.show_t=0
    def draw(self,t):
        liquid_bg(self.screen,t)
        self.screen.blit(glass(W-20,44,22,40),(10,8))
        text(self.screen,f"SIMON CANTA en {self.lang.upper()}  -  teclas 1-4  -  ronda {len(self.seq)}",W//2,30,self.f22)
        for i,p in enumerate(PADS):
            on=(self.flash==i and self.flash_t>0)
            self.screen.blit(glass(180,220,24,90 if on else 30),(p['x']-90,150))
            pygame.draw.circle(self.screen,p['c'],(p['x'],260),60 if on else 46)
            pygame.draw.circle(self.screen,(255,255,255),(p['x']-14,240),10 if on else 6)
            text(self.screen,WORDS[self.lang][i],p['x'],400,self.f22)
            text(self.screen,str(i+1),p['x'],130,self.f18,PINK)
        text(self.screen,'ESCUCHA...' if self.phase=='show' else 'TU TURNO: REPITE CANTANDO',W//2,H-40,self.f22,PINK)
        self.hud(t)

if __name__=='__main__': SimonCanta().run()
