wf('adapt_pong_phonetics.py', '''"""PONG FONETICO: rally de silabas con voz; cada 4 golpes, quiz de palabra escuchada."""
import pygame, random
from belentani_engine import *

WORDS=[('es','escuela',['es-cue-la']),('es','biblioteca',['bi-blio-te-ca']),
       ('ca','escola',['es-co-la']),('ca','biblioteca',['bi-bli-o-te-ca']),
       ('en','school',['school']),('en','library',['li-brary'])]
class PongFonetico(BaseGame):
    NAME='PONG FONETICO'
    def setup(self):
        self.py=H//2; self.ay=H//2; self.rally=0; self.syl=0; self.quiz=None
        self.new_word(); self.reset_ball(1)
    def new_word(self):
        self.lang,self.word,self.syls=random.choice(WORDS); self.syl=0
    def reset_ball(self,d):
        self.bx,self.by=W//2,H//2
        self.vx,self.vy=300*d,random.choice([-140,140])
    def on_event(self,e):
        if self.quiz and e.type==pygame.KEYDOWN and e.key in (pygame.K_1,pygame.K_2,pygame.K_3):
            i=e.key-pygame.K_1; self.total+=1
            if self.quiz['o'][i]==self.word:
                self.score+=200; self.add_streak(); self.hits+=1; say(self.word)
            else:
                self.lives-=1; self.streak=0
                if self.lives<=0: self.running=False
            self.quiz=None; self.new_word(); self.reset_ball(1)
    def update(self,dt,t):
        if self.quiz: return
        k=pygame.key.get_pressed()
        mv=(k[pygame.K_DOWN] or k[pygame.K_s])-(k[pygame.K_UP] or k[pygame.K_w])
        self.py=min(H-60,max(60,self.py+mv*360*dt))
        self.ay+=max(-260*dt,min(260*dt,self.by-self.ay))
        self.bx+=self.vx*dt; self.by+=self.vy*dt
        if self.by<20 or self.by>H-20: self.vy=-self.vy
        if self.bx<60 and abs(self.by-self.py)<55 and self.vx<0:
            self.vx=abs(self.vx)*1.05; self.rally+=1
            say(self.syls[self.syl%len(self.syls)]); self.syl+=1; beep(500)
            if self.rally%4==0: self.make_quiz()
        if self.bx>W-60 and abs(self.by-self.ay)<55 and self.vx>0:
            self.vx=-abs(self.vx)*1.05; beep(380)
        if self.bx<0:
            self.lives-=1; self.streak=0
            if self.lives<=0: self.running=False
            else: self.reset_ball(1)
        if self.bx>W:
            self.score+=50; self.reset_ball(-1)
    def make_quiz(self):
        others=[w for l,w,_ in WORDS if l==self.lang and w!=self.word]
        opts=[self.word]+others[:2]
