class Store:
    def __init__(self):
        pygame.init()
        self.screen=pygame.display.set_mode((W,H))
        pygame.display.set_caption('BELENTANI GAME STORE')
        self.tab=0; self.idx=0; self.toast=''; self.toast_t=0; self.fi=0
        self.joy=None
        if pygame.joystick.get_count():
            self.joy=pygame.joystick.Joystick(0); self.joy.init()
        self.frames=self._load_turntable()
    def _load_turntable(self):
        p=os.path.join(os.path.dirname(__file__),'assets','sprites','belentani_turntable.gif')
        fr=[]
        if os.path.exists(p):
            try:
                im=pygame.image.load(p)
                for _ in range(40):
                    fr.append(pygame.transform.smoothscale(im,(170,230)))
                    try: im.seek(im.tell()+1)
                    except EOFError: break
            except Exception: pass
        return fr
    def tiles(self):
        tb=TABS[self.tab]
        if tb=='GIT':
            return [{'key':'-','t':v['repo'].upper()[:14],'g':v['lic'],'src':v['repo'],'d':v['url'],'git':v['url']} for v in ADAPTATIONS.values()]
        if tb=='LOGROS':
            rows=top_scores()
            return [{'key':'-','t':g.upper()[:14],'g':'RECORD','src':'db','d':f'Mejor: {s}'} for g,s in rows] or [{'key':'-','t':'SIN RECORDS','g':'-','src':'-','d':'Juega para registrar'}]
        base=TILES_JUEGOS
        if tb=='IDIOMAS': base=[t for t in base if 'lang' in t['tags']]
        if tb=='MATES': base=[t for t in base if 'math' in t['tags']]
        if tb=='INICIO': return base[:5]
        return base
    def handle(self,e):
        if e.type==pygame.KEYDOWN:
            if e.key==pygame.K_ESCAPE: return 'quit'
            if e.key==pygame.K_q: self.tab=(self.tab-1)%len(TABS); self.idx=0
            if e.key==pygame.K_e: self.tab=(self.tab+1)%len(TABS); self.idx=0
            if e.key==pygame.K_LEFT: self.idx=max(0,self.idx-1)
            if e.key==pygame.K_RIGHT: self.idx=min(len(self.tiles())-1,self.idx+1)
            if e.key==pygame.K_RETURN: self.launch()
            if e.key==pygame.K_g: self.clone()
        if e.type==pygame.JOYHATMOTION:
            if e.value[0]<0: self.idx=max(0,self.idx-1)
            if e.value[0]>0: self.idx=min(len(self.tiles())-1,self.idx+1)
        if e.type==pygame.JOYBUTTONDOWN:
            if e.button==0: self.launch()
            if e.button==1: return 'quit'
            if e.button==4: self.tab=(self.tab-1)%len(TABS); self.idx=0
            if e.button==5: self.tab=(self.tab+1)%len(TABS); self.idx=0
        return None
    def launch(self):
        ts=self.tiles()
        if self.idx>=len(ts): return
        t=ts[self.idx]
        if t['key'].isdigit():
            subprocess.run([sys.executable,'play.py',t['key']])
            self.toast='Cargando '+t['t']; self.toast_t=2
    def clone(self):
        ts=self.tiles(); t=ts[self.idx] if self.idx<len(ts) else None
        if t and t.get('git'):
            subprocess.run(['git','clone','--depth','1',t['git'],'clones/'+t['src']])
            self.toast='Clonado '+t['src']; self.toast_t=2.5
    def update(self,dt,t):
        self.toast_t=max(0,self.toast_t-dt)
        if self.frames: self.fi=int(t/90)%len(self.frames)
    def draw(self,t):
        liquid_bg(self.screen,t)
        self.screen.blit(red_glass(W-40,64,False,40),(20,12))
        text(self.screen,'BELENTANI GAME STORE',40,44,self.f30,center=False)
        for i,tb in enumerate(TABS):
            x=430+i*88; sel=i==self.tab
            self.screen.blit(red_glass(82,40,sel,30),(x,24))
            text(self.screen,tb,x+41,44,self.f16,WHITE if sel else PINK)
        if self.frames: self.screen.blit(self.frames[self.fi],(36,96))
        else: draw_bel(self.screen,120,210,180,t)
        ts=self.tiles(); self.idx=min(self.idx,max(0,len(ts)-1))
        for i,tl in enumerate(ts):
            x=250+(i-self.idx)*210
            if x<-220 or x>W: continue
            sel=i==self.idx
            self.screen.blit(red_glass(200,240,sel),(x,150))
            if sel:
                sw=60; sx=x+((t//8)%(200+sw))-sw
                gl=pygame.Surface((sw,240),pygame.SRCALPHA)
                for c in range(sw):
                    a=int(60*(1-abs(c-sw/2)/(sw/2)))
                    pygame.draw.line(gl,(255,255,255,a),(c,0),(c,240))
                self.screen.blit(gl,(sx,150))
            text(self.screen,tl['t'][:14],x+100,200,self.f22)
            text(self.screen,tl['g'],x+100,240,self.f16,PINK)
            text(self.screen,tl['src'][:18],x+100,350,self.f16,GOOD)
        if ts:
            cur=ts[self.idx]
            self.screen.blit(red_glass(W-40,80,False,30),(20,H-104))
            text(self.screen,cur['t']+' - '+cur['d'],40,H-64,self.f18,center=False)
        text(self.screen,'A(ENTER) jugar   B(ESC) salir   Q/E tabs   G clonar repo',W//2,H-14,self.f16,PINK)
        if self.toast_t>0:
            self.screen.blit(red_glass(420,50,True,50),(W//2-210,84))
            text(self.screen,self.toast,W//2,109,self.f18)
    def run(self):
        clock=pygame.time.Clock()
        while True:
            dt=clock.tick(60)/1000; t=pygame.time.get_ticks()
            for e in pygame.event.get():
                if e.type==pygame.QUIT: pygame.quit(); return
                if self.handle(e)=='quit': pygame.quit(); return
            self.update(dt,t); self.draw(t); pygame.display.flip()

if __name__=='__main__': Store().run()
