const DEF:ShieldSettings={dailyMin:90,curfew:'21:30',breakMin:25,externalAI:false,voice:true,pinHash:''};
async function hash(p:string){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(p));
 return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('');}
export default function ParentalShield({set,onClose}:{set:(s:ShieldSettings)=>void;onClose:()=>void}){
