// server.ts — local-only, sin salidas externas
import http from 'http'; import fs from 'fs'; import path from 'path';
const MIME:Record<string,string>={'.html':'text/html','.js':'text/javascript','.css':'text/css','.json':'application/json','.png':'image/png'};
http.createServer((req,res)=>{
  const u=req.url||'/'; res.setHeader('Cache-Control','no-store');
  if(u==='/api/bank'){const p=path.join(process.cwd(),'belentani_school_bank.json');
    if(fs.existsSync(p)){res.setHeader('Content-Type','application/json');return res.end(fs.readFileSync(p));}
    return res.end(JSON.stringify({error:'genera el banco con generators/gen_bank.py'}));}
  if(u==='/api/health')return res.end(JSON.stringify({local:true,telemetry:false}));
  const f=path.join(process.cwd(),'dist',u==='/'?'index.html':u);
  fs.readFile(f,(e,d)=>{if(e){res.statusCode=404;return res.end('404');}
    res.setHeader('Content-Type',MIME[path.extname(f)]||'application/octet-stream');res.end(d);});
}).listen(8080,'127.0.0.1',()=>console.log('BELENTANI SCHOOL local en http://127.0.0.1:8080'));
