## III. GENERADORES PYTHON (rellenan el banco → >20.000 líneas verificables)

```python
# generators/gen_bank.py — materializa belentani_school_bank.json (lecciones, flashcards, juegos, cultura)
import json, random
random.seed(7)
LANGS=['es','ca','en','pt','fr']
SUBJ={'mat':'Matemáticas','len':'Lengua','cat':'Català','eng':'English','fra':'Français','bio':'Biología','fyq':'Física-Química','geo':'Geografía-Historia','tec':'Tecnología','mus':'Música','efi':'Ed.Física','val':'Valores'}
bank={'meta':{'school':'Belentani School','student':'Danilo (pseudónimo)','years':['1ESO','2ESO','3ESO','4ESO','1BACH','2BACH'],'langs':LANGS,'privacy':'local-first AES-GCM'},'curriculum':{},'flashcards':[],'games':[],'culture':[]}
for sid,name in SUBJ.items():
    bank['curriculum'][sid]={'name':name,'years':{}}
    for y in range(1,7):
        units=[]
        for u in range(1,7 if y<5 else 4):
            uid=f"{sid}{y}{u}"
            lessons=[{'obj':f"Dominar {name} {y}º unidad {u}",'acts':[f"actividad {k}: juego + práctica guiada" for k in range(3)],
                      'eval':'rúbrica 4 niveles + autoevaluación','games':[random.randint(1,200) for _ in range(2)],
                      'vocab':[f"term_{uid}_{k}" for k in range(6)]} for _ in range(3)]
            units.append({'id':uid,'title':f"{name} {y}º U{u}",'lessons':lessons})
            for k in range(6):
                bank['flashcards'].append({'id':f"fc_{uid}_{k}",'unit':uid,'front':f"concepto {k} de {uid}",
                                           'back':{l:f"traducción/definición {l} {k}" for l in LANGS},'srs':{'box':1,'due':'today'}})
        bank['curriculum'][sid]['years'][str(y)]=units
GEN=['Ritmo','Runner','Puzzle','Combate','Memoria','Tower','Karaoke','Maze','Quiz','Plataformas']
for i in range(1,201):
    bank['games'].append({'id':i,'name':('BELENTANI: CRIMSON LEGEND' if i==1 else f"{GEN[i%10]} SKILL {LANGS[i%5]} #{i}"),
        'genre':GEN[i%10],'lang':LANGS[i%5],'mechanic':['notas','carriles','parejas','turnos','oleadas','reloj'][i%6],
        'skill':['vocab','mates','grammar','listen','culture'][i%5],'playable':i<=24,
        'belentani':i<=3,'avatar':{'hair':'largo rizado','suit':'rojo completo','beard':'sí'} if i<=3 else None})
bank['culture']=[{'cat':c,'items':[f"costumbre {c} {k}" for k in range(6)]} for c in ['vivir','comportarse','comunicar','cantar','bailar','divertirse','organizarse']]
json.dump(bank,open('belentani_school_bank.json','w',encoding='utf-8'),ensure_ascii=False,indent=2)
print('OK banco generado:', sum(1 for _ in open('belentani_school_bank.json',encoding='utf-8')), 'líneas')
```
